let growth=0.1; // 0-1
function updatePlant(p,dt){
  if(weather.rain) growth+=dt*0.00018;
  if(isDay) growth+=dt*0.00006;
  const sway=Math.sin(time*0.014 + p.x*0.09)*0.7;
  const s=growth<0.33?0.5:growth<0.66?0.75:1.0;
  ctx.save(); ctx.translate(p.x+sway, p.y);
  ctx.drawImage(tex, 0,0,16,16, 8*(1-s),8*(1-s),16*s,16*s);
  ctx.restore();
  if(growth>0.9 && Math.random()<0.0004) spreadToNeighbor(p); // Terraria spread
}
